DROP TABLE IF EXISTS `permits`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `permits` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `permit_type` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sader',
  `permit_no` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `permit_date` date DEFAULT NULL,
  `company` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `client` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `destination` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_co` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agency` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `port` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `containers` int NOT NULL DEFAULT '0',
  `container_type` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_rate` decimal(10,2) DEFAULT NULL,
  `guarantee_rate` decimal(10,2) DEFAULT NULL,
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(12) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_type` (`permit_type`),
  KEY `idx_no` (`permit_no`),
  KEY `idx_date` (`permit_date`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

